mapper.select:
SELECT m.code, m.grade, m.class_no as classNo, m.name, m.college_id as collegeId, c.name as collegeName, m.head_teacher_id as headTeacherId, t.teacher_number as headTeacherNumber, u.real_name as headTeacherName, m.status, CASE WHEN m.status = 0 THEN '正常' WHEN m.status = 1 THEN '停招' WHEN m.status = 2 THEN '撤销' ELSE '未知' END as statusText, m.create_time as createTime, m.update_time as updateTime, m.create_by as createBy, m.update_by as updateBy, m.is_deleted as isDeleted, (SELECT COUNT(*) FROM students s WHERE s.major_code = m.code AND s.grade = m.grade AND s.class_no = m.class_no AND s.is_deleted = 0 and s.status = 0) as studentCount FROM majors m LEFT JOIN colleges c ON m.college_id = c.id AND c.is_deleted = 0 LEFT JOIN teachers t ON m.head_teacher_id = t.id LEFT JOIN users u ON t.user_id = u.id AND u.is_deleted = 0 WHERE m.is_deleted = 0
AND m.code LIKE CONCAT('%', #{code}, '%')
AND m.name LIKE CONCAT('%', #{name}, '%')
AND m.grade = #{grade}
AND m.college_id = #{collegeId}
AND m.status = #{status}
ORDER BY m.grade DESC, m.class_no ASC LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM majors m
WHERE m.is_deleted = 0

    AND m.name LIKE CONCAT('%', #{name}, '%')


    AND m.grade = #{grade}


    AND m.college_id = #{collegeId}


    AND m.status = #{status}

SELECT COUNT(1)
FROM students s
WHERE s.major_code = #{code}
AND s.grade = #{grade}
AND s.class_no = #{classNo}
AND s.status = 0
AND s.is_deleted = 0

